CREATE TABLE `course_files` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `batch_subject_id` bigint(20) unsigned NOT NULL,
  `syllabus_pdf_path` varchar(255) DEFAULT NULL,
  `parsed_modules` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`parsed_modules`)),
  `parsed_cos` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`parsed_cos`)),
  `parsed_copo` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`parsed_copo`)),
  `parsed_textbooks` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`parsed_textbooks`)),
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `assignment_deadlines` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`assignment_deadlines`)),
  `assignment_questions` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`assignment_questions`)),
  `summative_manual_tests` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`summative_manual_tests`)),
  `self_learning_configs` text DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `course_files_batch_subject_id_foreign` (`batch_subject_id`),
  CONSTRAINT `course_files_batch_subject_id_foreign` FOREIGN KEY (`batch_subject_id`) REFERENCES `batch_subjects` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `course_files` (`id`, `batch_subject_id`, `syllabus_pdf_path`, `parsed_modules`, `parsed_cos`, `parsed_copo`, `parsed_textbooks`, `created_at`, `updated_at`, `assignment_deadlines`, `assignment_questions`, `summative_manual_tests`, `self_learning_configs`) VALUES ('2', '5', 'r26_syllabi/wSXpMFNNHcMQJNpfin1P6zyVh3ePa9pYWP0zBjfd.pdf', '\"[{\\\"module_id\\\":\\\"I\\\",\\\"title\\\":\\\"Matrices & Determinants\\\",\\\"hours\\\":15,\\\"content\\\":\\\"Basic concept of a matrix, special types of matrices, Transpose of a matrix Algebra of matrices: Multiplication by, a scalar, Equality, Addition, Subtraction, Matrix Multiplication Determinants, Solution of system of, linear equations involving two and three unknowns by Cramer\'s rule, Minors, cofactors, adjoint and inverse of a 2 X 2 matrix, Problems\\\"},{\\\"module_id\\\":\\\"II\\\",\\\"title\\\":\\\"Trigonometry\\\",\\\"hours\\\":15,\\\"content\\\":\\\"Angles, Trigonometric ratios of acute angle, Trigonometric ratios of standard angles, Pythagorean relations, Trigonometric ratios of any angle, ASTC rule, Reduction formula, Trigonometric ratios of compound angles (A+B, A-B), Problems\\\"},{\\\"module_id\\\":\\\"III\\\",\\\"title\\\":\\\"Coordinate Geometry\\\",\\\"hours\\\":16,\\\"content\\\":\\\"Straight lines: Slope, slope-point form, Angle between lines, Parallel and perpendicular lines, Circles: Equation of a circle, center and radius of the circle, Problems\\\"},{\\\"module_id\\\":\\\"IV\\\",\\\"title\\\":\\\"Differential Calculus\\\",\\\"hours\\\":15,\\\"content\\\":\\\"Concept of limit, Limits by substitution and factorisation, Limits of the form (xn - an) \\\\\\/ (x-a) and sin x \\\\\\/ x, Basic concept of di\\\\ufb00erentiation, standard results (derivatives of a constant k, xn, ex, log x, sin x, cos x, tan x, csc x, sec x, cot x) Rules of di\\\\ufb00erentiation (linearity,, product, and quotient rules), second derivatives, Problems\\\"}]\"', '\"[{\\\"id\\\":\\\"CO1\\\",\\\"description\\\":\\\"Apply the concepts of matrices and determinants to solve linear systems of equations involving two and three unknowns.\\\",\\\"cognitive_level\\\":\\\"Apply\\\",\\\"duration\\\":15},{\\\"id\\\":\\\"CO2\\\",\\\"description\\\":\\\"Use trigonometric identities and functions to solve trigonometric problems.\\\",\\\"cognitive_level\\\":\\\"Apply\\\",\\\"duration\\\":15},{\\\"id\\\":\\\"CO3\\\",\\\"description\\\":\\\"Interpret geometric problems related to straight lines and circles using Coordinate geometric concepts.\\\",\\\"cognitive_level\\\":\\\"Apply\\\",\\\"duration\\\":15},{\\\"id\\\":\\\"CO4\\\",\\\"description\\\":\\\"Evaluate limits and derivatives.\\\",\\\"cognitive_level\\\":\\\"Apply\\\",\\\"duration\\\":15}]\"', '\"{\\\"credit\\\":4,\\\"l_t_p_r\\\":\\\"3:1:0:0\\\",\\\"cie_marks\\\":40,\\\"ese_marks\\\":60,\\\"total_hours\\\":60,\\\"mappings\\\":{\\\"CO1\\\":{\\\"PO1\\\":\\\"3\\\",\\\"PO2\\\":\\\"-\\\",\\\"PO3\\\":\\\"-\\\",\\\"PO4\\\":\\\"-\\\",\\\"PO5\\\":\\\"-\\\",\\\"PO6\\\":\\\"-\\\",\\\"PO7\\\":\\\"-\\\",\\\"PO8\\\":\\\"-\\\",\\\"PO9\\\":\\\"-\\\",\\\"PO10\\\":\\\"-\\\",\\\"PO11\\\":\\\"-\\\"},\\\"CO2\\\":{\\\"PO1\\\":\\\"3\\\",\\\"PO2\\\":\\\"-\\\",\\\"PO3\\\":\\\"-\\\",\\\"PO4\\\":\\\"-\\\",\\\"PO5\\\":\\\"-\\\",\\\"PO6\\\":\\\"-\\\",\\\"PO7\\\":\\\"-\\\",\\\"PO8\\\":\\\"-\\\",\\\"PO9\\\":\\\"-\\\",\\\"PO10\\\":\\\"-\\\",\\\"PO11\\\":\\\"-\\\"},\\\"CO3\\\":{\\\"PO1\\\":\\\"3\\\",\\\"PO2\\\":\\\"-\\\",\\\"PO3\\\":\\\"-\\\",\\\"PO4\\\":\\\"-\\\",\\\"PO5\\\":\\\"-\\\",\\\"PO6\\\":\\\"-\\\",\\\"PO7\\\":\\\"-\\\",\\\"PO8\\\":\\\"-\\\",\\\"PO9\\\":\\\"-\\\",\\\"PO10\\\":\\\"-\\\",\\\"PO11\\\":\\\"-\\\"},\\\"CO4\\\":{\\\"PO1\\\":\\\"3\\\",\\\"PO2\\\":\\\"-\\\",\\\"PO3\\\":\\\"-\\\",\\\"PO4\\\":\\\"-\\\",\\\"PO5\\\":\\\"-\\\",\\\"PO6\\\":\\\"-\\\",\\\"PO7\\\":\\\"-\\\",\\\"PO8\\\":\\\"-\\\",\\\"PO9\\\":\\\"-\\\",\\\"PO10\\\":\\\"-\\\",\\\"PO11\\\":\\\"-\\\"}}}\"', '\"[\\\"Textbook Reference 1\\\",\\\"Textbook Reference 2\\\"]\"', '2026-08-11 21:58:19', '2026-08-11 22:24:52', NULL, NULL, NULL, NULL);
INSERT INTO `course_files` (`id`, `batch_subject_id`, `syllabus_pdf_path`, `parsed_modules`, `parsed_cos`, `parsed_copo`, `parsed_textbooks`, `created_at`, `updated_at`, `assignment_deadlines`, `assignment_questions`, `summative_manual_tests`, `self_learning_configs`) VALUES ('3', '16', '/storage/syllabi/BSXp5xnljBWEqZnoaA8W2h9A6yGLlTQzmCGl29ks.pdf', '[{\"module_id\":\"I\",\"content\":\"Introduction to highway engineering and traffic engineering Role of transportation in the development of nation - IRC - IRC classification of road - Major SH and NH in Kerala. - Road alignment - Factors to be considered in road alignment Traffic Engineering: - Traffic volume study - Traffic intensity studies - OD studies - Road intersection studies - Intersections - types of at grade intersection - Channelizing islands - pedestrian loading islands - Rotary islands - Grade separated intersections - Clover leaf junction - Trumpet junction - Road markings - Traffic signs - Types and purpose of signs - Mandatory, cautionary, informatory and temporary signs.\"},{\"module_id\":\"II\",\"content\":\"Highway Geometrics: Standards cross-sections of national highway in embankment and cutting- various components- Camber - Gradient - Design speed -Sight distance (SSD), road arboriculture- Road drainage Curves: Necessity, types: Horizontal, vertical curves - Extra widening of roads - transition curve- Super elevation: Definition and formula Types of road materials and their Tests - Test on aggregates - Types of Bitumen and its properties, Pavement - Definition, Types, Structural Components of pavement and their functions- Construction of Flexible pavement \\/ Bituminous Road Emulsion, Cutback, Tar, Granular Sub Base (GSB), Wet Mix Macadam (WMM), Bituminous Macadam & Bituminous Concrete (BM & BC), Natural Rubber Modified Bitumen (NRMB). Use of shredded plastic - Rigid pavement, Cement concrete road - methods of construction, Alternate and Continuous Bay Method, Construction joints, filler and sealers, White topping, merits and demerits of concrete roads.\"},{\"module_id\":\"III\",\"content\":\"Railway Engineering Classification of Indian Railways, zones of Indian Railways - Permanent way: Ideal requirement, Components - Rail Gauge - Rail, Rail Joints - requirements, types - Creep of rail: causes and prevention - Sleepers, Ballast - functions and types - Rail fixtures and fastenings - Railway Track Geometrics: Gradient, curves, grade compensation, super elevation, cant deficiency, negative cant, coning of wheel, tilting of rail, Track Cross sections - standard cross section of single and double line in cutting and embankment Points and crossings - Turn out - types, components, functions - Track junctions: crossovers, scissor cross over, diamond crossing, Track signals -principles of interlocking - Station yard: Classifications Overview of Mono Rail and Metro rail\"},{\"module_id\":\"IV\",\"content\":\"Bridge, Tunnel, Airport and Harbour engineering Bridge Engineering: Terminologies in bridge engineering - IRC classification - Bridge components - Foundation, Abutment, Pier, wing wall, deck slab, bridge bearing, girder beam and approach road. Tunneling: Need for tunneling work, Terminologies in tunneling, Tunnel boring machine (TBM) common shapes of tunnels. Airport Engineering:- airport components - Runway, Apron, taxi way, terminal building, hangers, cargo, Fueling facility, Fire fighting, parking and circulation area - layout of an airport, selection of site for airport Docks and Harbours: - Definitions - classification and their functions - components of dock and harbour -Wharf, break waters - types - Layout.\"}]', '[{\"id\":\"CO1\",\"description\":\"Summarize the components of various transportation systems and collection of traffic\",\"duration\":13,\"cognitive_level\":\"Understanding\"},{\"id\":\"CO2\",\"description\":\"Identity the various material tests and construction methods of road.\",\"duration\":15,\"cognitive_level\":\"Understanding\"},{\"id\":\"CO3\",\"description\":\"Illustrate the geometrical design features of roadways and railways\",\"duration\":15,\"cognitive_level\":\"Applying\"},{\"id\":\"CO4\",\"description\":\"Outline the different modes of transportation and        importance of bridge and tunnel\",\"duration\":15,\"cognitive_level\":\"Understanding\"}]', '{\"CO1\":{\"PO1\":3,\"PO2\":2,\"PO3\":1,\"PO4\":null,\"PO5\":null,\"PO6\":null,\"PO7\":null,\"PO8\":null,\"PO9\":null,\"PO10\":null,\"PO11\":null,\"PO12\":null},\"CO2\":{\"PO1\":2,\"PO2\":3,\"PO3\":2,\"PO4\":1,\"PO5\":null,\"PO6\":null,\"PO7\":null,\"PO8\":null,\"PO9\":null,\"PO10\":null,\"PO11\":null,\"PO12\":null},\"CO3\":{\"PO1\":1,\"PO2\":2,\"PO3\":3,\"PO4\":2,\"PO5\":1,\"PO6\":null,\"PO7\":null,\"PO8\":null,\"PO9\":null,\"PO10\":null,\"PO11\":null,\"PO12\":null},\"CO4\":{\"PO1\":null,\"PO2\":1,\"PO3\":2,\"PO4\":3,\"PO5\":2,\"PO6\":null,\"PO7\":null,\"PO8\":null,\"PO9\":null,\"PO10\":null,\"PO11\":null,\"PO12\":null}}', '[\"Standard Reference Textbook for the Subject.\"]', '2026-08-11 22:16:01', '2026-08-12 20:02:13', NULL, NULL, NULL, NULL);
INSERT INTO `course_files` (`id`, `batch_subject_id`, `syllabus_pdf_path`, `parsed_modules`, `parsed_cos`, `parsed_copo`, `parsed_textbooks`, `created_at`, `updated_at`, `assignment_deadlines`, `assignment_questions`, `summative_manual_tests`, `self_learning_configs`) VALUES ('4', '23', '/storage/syllabi/tRXaWzNtuq1cTCqbn5jOiTGwdgTWOH83SpH9Msf1.pdf', '[{\"module_id\":\"I\",\"content\":\"\"},{\"module_id\":\"II\",\"content\":\"\"},{\"module_id\":\"III\",\"content\":\"\"},{\"module_id\":\"IV\",\"content\":\"\"},{\"module_id\":\"V\",\"content\":\"\"},{\"module_id\":\"VI\",\"content\":\"\"}]', '[{\"id\":\"CO1\",\"description\":\"To illustrate the concept of limit state design and detailing of RCC beams and slabs.\",\"duration\":12,\"cognitive_level\":\"Applying\"},{\"id\":\"CO2\",\"description\":\"To illustrate the concept of limit state design and detailing of RCC columns, footings and stairs.\",\"duration\":17,\"cognitive_level\":\"Applying\"},{\"id\":\"CO3\",\"description\":\"To illustrate the concept of limit state design and detailing of tension and compression steel members. Lab Tests \\t4\",\"duration\":14,\"cognitive_level\":\"Applying\"}]', '{\"CO1\":{\"PO1\":null,\"PO2\":3,\"PO3\":null,\"PO4\":null,\"PO5\":null,\"PO6\":null,\"PO7\":null,\"PO8\":null,\"PO9\":null,\"PO10\":null,\"PO11\":null,\"PO12\":null},\"CO2\":{\"PO1\":null,\"PO2\":3,\"PO3\":null,\"PO4\":null,\"PO5\":null,\"PO6\":null,\"PO7\":null,\"PO8\":null,\"PO9\":null,\"PO10\":null,\"PO11\":null,\"PO12\":null},\"CO3\":{\"PO1\":null,\"PO2\":3,\"PO3\":null,\"PO4\":null,\"PO5\":null,\"PO6\":null,\"PO7\":null,\"PO8\":null,\"PO9\":null,\"PO10\":null,\"PO11\":null,\"PO12\":null}}', '[\"Standard Reference Textbook for the Subject.\"]', '2026-08-12 16:23:23', '2026-08-12 17:16:54', NULL, NULL, NULL, NULL);
