CREATE TABLE `r26_drawing_course_files` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `batch_subject_id` bigint(20) unsigned NOT NULL,
  `syllabus_pdf_path` varchar(255) DEFAULT NULL,
  `program` text DEFAULT NULL,
  `course_title` varchar(255) DEFAULT NULL,
  `course_code` varchar(50) DEFAULT NULL,
  `semester` varchar(20) DEFAULT NULL,
  `type_of_course` varchar(255) NOT NULL DEFAULT 'Lab',
  `teaching_scheme` varchar(50) NOT NULL DEFAULT '0:0:3:0',
  `contact_hours` int(11) NOT NULL DEFAULT 45,
  `credits` decimal(4,1) NOT NULL DEFAULT 1.5,
  `cie_marks` int(11) NOT NULL DEFAULT 60,
  `ese_marks` int(11) NOT NULL DEFAULT 40,
  `parsed_cos` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`parsed_cos`)),
  `parsed_modules` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`parsed_modules`)),
  `parsed_exercises` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`parsed_exercises`)),
  `parsed_copo` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`parsed_copo`)),
  `parsed_textbooks` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`parsed_textbooks`)),
  `self_learning_configs` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`self_learning_configs`)),
  `series_test_qps` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`series_test_qps`)),
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `r26_drawing_course_files_batch_subject_id_unique` (`batch_subject_id`),
  CONSTRAINT `r26_drawing_course_files_batch_subject_id_foreign` FOREIGN KEY (`batch_subject_id`) REFERENCES `batch_subjects` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `r26_drawing_course_files` (`id`, `batch_subject_id`, `syllabus_pdf_path`, `program`, `course_title`, `course_code`, `semester`, `type_of_course`, `teaching_scheme`, `contact_hours`, `credits`, `cie_marks`, `ese_marks`, `parsed_cos`, `parsed_modules`, `parsed_exercises`, `parsed_copo`, `parsed_textbooks`, `self_learning_configs`, `series_test_qps`, `created_at`, `updated_at`) VALUES ('1', '7', 'r26_drawing_syllabi/lgwsFFUStTHGEofjIBWXvWRyccQk25HC9EddMFRM.pdf', 'Electrical Engineering, Electrical Engineering & Electric Vehicles Technology, Fire Technology and', 'Engineering Graphics', '1003', 'I', 'Lab', '0:0:3:0', '45', '1.5', '40', '60', '[{\"id\":\"CO1\",\"description\":\"Illustrate the basic elements of drawing.\",\"cognitive_level\":\"Understand\"},{\"id\":\"CO2\",\"description\":\"Construct geometrical \\ufb01gures and illustrate development of surfaces.\",\"cognitive_level\":\"Apply\"},{\"id\":\"CO3\",\"description\":\"Interpret projections of points and lines.\",\"cognitive_level\":\"Understand\"},{\"id\":\"CO4\",\"description\":\"Develop orthographic projections and sectional views of objects.\",\"cognitive_level\":\"Apply\"}]', '[{\"module_id\":\"I\",\"title\":\"Engineering Graphics Fundamentals & Conic Sections\",\"hours\":9,\"content\":\"Regular Polygons, Ellipse, Parabola, Development of Surfaces\"},{\"module_id\":\"II\",\"title\":\"Projections & Sectional Views\",\"hours\":12,\"content\":\"Projections of Points, Lines, Orthographic Projections, Sectional Views\"},{\"module_id\":\"III\",\"title\":\"Computer Aided Drafting (CAD) Basics\",\"hours\":12,\"content\":\"CAD editor, Draw\\/Modify commands, Line properties, Text, Dimensions\"},{\"module_id\":\"IV\",\"title\":\"CAD 2D Drafting & Plotting\",\"hours\":12,\"content\":\"Orthographic components in CAD, Sectional views in CAD, Printing\\/Plotting\"}]', '[{\"exercise_no\":\"EXE-01\",\"module\":\"Module I\",\"title\":\"Drawing Sheet 1 - Regular Polygons (Pentagon & Hexagon)\",\"co_id\":\"CO1\",\"hours\":3},{\"exercise_no\":\"EXE-02\",\"module\":\"Module I\",\"title\":\"Drawing Sheet 2 - Conic Sections (Ellipse, Parabola)\",\"co_id\":\"CO1\",\"hours\":3},{\"exercise_no\":\"EXE-03\",\"module\":\"Module I\",\"title\":\"Drawing Sheet 3 - Development of Surfaces (Prism & Cylinder)\",\"co_id\":\"CO1\",\"hours\":3},{\"exercise_no\":\"EXE-04\",\"module\":\"Module II\",\"title\":\"Drawing Sheet 4 - Projections of Points & Lines in Quadrants\",\"co_id\":\"CO2\",\"hours\":6},{\"exercise_no\":\"EXE-05\",\"module\":\"Module II\",\"title\":\"Drawing Sheet 5 - Orthographic Projections & Sectional Views\",\"co_id\":\"CO2\",\"hours\":6},{\"exercise_no\":\"EXE-06\",\"module\":\"Module III\",\"title\":\"CAD Sheet 6 - CAD Editor Draw & Modify Commands\",\"co_id\":\"CO3\",\"hours\":6},{\"exercise_no\":\"EXE-07\",\"module\":\"Module III\",\"title\":\"CAD Sheet 7 - Layers, Line Properties, Text & Dimensioning\",\"co_id\":\"CO3\",\"hours\":6},{\"exercise_no\":\"EXE-08\",\"module\":\"Module IV\",\"title\":\"CAD Sheet 8 - 2D Orthographic Drafting of Engineering Objects\",\"co_id\":\"CO4\",\"hours\":6},{\"exercise_no\":\"EXE-09\",\"module\":\"Module IV\",\"title\":\"CAD Sheet 9 - Sectional Views & Final CAD Sheet Plotting\",\"co_id\":\"CO4\",\"hours\":6}]', '{\"credit\":1.5,\"l_t_p_r\":\"0:0:3:0\",\"cie_marks\":40,\"ese_marks\":60,\"total_hours\":45,\"mappings\":{\"CO1\":{\"PO1\":\"3\",\"PO2\":\"1\",\"PO3\":\"-\",\"PO4\":\"-\",\"PO5\":\"2\",\"PO6\":\"-\",\"PO7\":\"-\",\"PO8\":\"-\",\"PO9\":\"1\",\"PO10\":\"-\",\"PO11\":\"-\"},\"CO2\":{\"PO1\":\"3\",\"PO2\":\"2\",\"PO3\":\"2\",\"PO4\":\"-\",\"PO5\":\"2\",\"PO6\":\"-\",\"PO7\":\"-\",\"PO8\":\"-\",\"PO9\":\"1\",\"PO10\":\"-\",\"PO11\":\"-\"},\"CO3\":{\"PO1\":\"3\",\"PO2\":\"3\",\"PO3\":\"2\",\"PO4\":\"1\",\"PO5\":\"2\",\"PO6\":\"-\",\"PO7\":\"-\",\"PO8\":\"-\",\"PO9\":\"1\",\"PO10\":\"-\",\"PO11\":\"-\"},\"CO4\":{\"PO1\":\"3\",\"PO2\":\"3\",\"PO3\":\"3\",\"PO4\":\"2\",\"PO5\":\"2\",\"PO6\":\"-\",\"PO7\":\"-\",\"PO8\":\"-\",\"PO9\":\"1\",\"PO10\":\"-\",\"PO11\":\"-\"}}}', '[\"Engineering Graphics with AUTOCAD - P I Varghese\",\"Engineering Graphics - K. C John\",\"Engineering Drawing with CAD Applications - N. D. Bhatt\"]', NULL, NULL, '2026-08-12 10:11:11', '2026-08-12 11:05:11');
INSERT INTO `r26_drawing_course_files` (`id`, `batch_subject_id`, `syllabus_pdf_path`, `program`, `course_title`, `course_code`, `semester`, `type_of_course`, `teaching_scheme`, `contact_hours`, `credits`, `cie_marks`, `ese_marks`, `parsed_cos`, `parsed_modules`, `parsed_exercises`, `parsed_copo`, `parsed_textbooks`, `self_learning_configs`, `series_test_qps`, `created_at`, `updated_at`) VALUES ('2', '36', NULL, 'Engineering', 'Engineering Graphics', 'ME-1003', '1', 'Lab', '0:0:3:0', '45', '1.5', '60', '40', '[{\"id\":\"CO1\",\"description\":\"Construct geometrical figures and illustrate development of surfaces.\",\"cognitive_level\":\"Apply\"},{\"id\":\"CO2\",\"description\":\"Interpret projections of points and lines, orthographic projections and sectional views.\",\"cognitive_level\":\"Apply\"},{\"id\":\"CO3\",\"description\":\"Familiarization in using CAD software and 2D drafting tools.\",\"cognitive_level\":\"Apply\"},{\"id\":\"CO4\",\"description\":\"Develop orthographic projections and sectional views in CAD software.\",\"cognitive_level\":\"Apply\"}]', '[{\"module_id\":\"I\",\"title\":\"Engineering Graphics Fundamentals & Conic Sections\",\"hours\":9,\"content\":\"Regular Polygons, Ellipse, Parabola, Development of Surfaces\"},{\"module_id\":\"II\",\"title\":\"Projections & Sectional Views\",\"hours\":12,\"content\":\"Projections of Points, Lines, Orthographic Projections, Sectional Views\"},{\"module_id\":\"III\",\"title\":\"Computer Aided Drafting (CAD) Basics\",\"hours\":12,\"content\":\"CAD editor, Draw\\/Modify commands, Line properties, Text, Dimensions\"},{\"module_id\":\"IV\",\"title\":\"CAD 2D Drafting & Plotting\",\"hours\":12,\"content\":\"Orthographic components in CAD, Sectional views in CAD, Printing\\/Plotting\"}]', '[{\"exercise_no\":\"EXE-01\",\"module\":\"Module I\",\"title\":\"Drawing Regular Polygons (Pentagon & Hexagon)\",\"co_id\":\"CO1\",\"hours\":3},{\"exercise_no\":\"EXE-02\",\"module\":\"Module I\",\"title\":\"Drawing Conic Sections (Ellipse by Rectangular & Concentric Circle Method)\",\"co_id\":\"CO1\",\"hours\":3},{\"exercise_no\":\"EXE-03\",\"module\":\"Module I\",\"title\":\"Drawing Development of Surfaces (Prism & Cylinder)\",\"co_id\":\"CO1\",\"hours\":3},{\"exercise_no\":\"EXE-04\",\"module\":\"Module II\",\"title\":\"Drawing Basic Projections of Points & Lines in Quadrants\",\"co_id\":\"CO2\",\"hours\":6},{\"exercise_no\":\"EXE-05\",\"module\":\"Module II\",\"title\":\"Drawing Orthographic Projections & Sectional Views of Engineering Objects\",\"co_id\":\"CO2\",\"hours\":6},{\"exercise_no\":\"EXE-06\",\"module\":\"Module III\",\"title\":\"CAD Software Basics & Familiarization of Draw and Modify Commands\",\"co_id\":\"CO3\",\"hours\":6},{\"exercise_no\":\"EXE-07\",\"module\":\"Module III\",\"title\":\"CAD Line Properties, Layers, Text, and Dimensioning Practice\",\"co_id\":\"CO3\",\"hours\":6},{\"exercise_no\":\"EXE-08\",\"module\":\"Module IV\",\"title\":\"Developing Orthographic Views of Components in CAD\",\"co_id\":\"CO4\",\"hours\":6},{\"exercise_no\":\"EXE-09\",\"module\":\"Module IV\",\"title\":\"Developing Sectional Views & Plotting CAD Drawings\",\"co_id\":\"CO4\",\"hours\":6}]', '{\"credit\":1.5,\"l_t_p_r\":\"0:0:3:0\",\"cie_marks\":60,\"ese_marks\":40,\"total_hours\":45,\"mappings\":{\"CO1\":{\"PO1\":\"3\",\"PO2\":\"2\",\"PO3\":\"3\",\"PO4\":\"-\",\"PO5\":\"-\",\"PO6\":\"-\",\"PO7\":\"-\",\"PO8\":\"-\",\"PO9\":\"-\",\"PO10\":\"-\",\"PO11\":\"-\"},\"CO2\":{\"PO1\":\"3\",\"PO2\":\"3\",\"PO3\":\"2\",\"PO4\":\"-\",\"PO5\":\"-\",\"PO6\":\"-\",\"PO7\":\"-\",\"PO8\":\"-\",\"PO9\":\"-\",\"PO10\":\"-\",\"PO11\":\"-\"},\"CO3\":{\"PO1\":\"2\",\"PO2\":\"-\",\"PO3\":\"2\",\"PO4\":\"3\",\"PO5\":\"-\",\"PO6\":\"-\",\"PO7\":\"-\",\"PO8\":\"-\",\"PO9\":\"-\",\"PO10\":\"-\",\"PO11\":\"-\"},\"CO4\":{\"PO1\":\"3\",\"PO2\":\"2\",\"PO3\":\"3\",\"PO4\":\"3\",\"PO5\":\"-\",\"PO6\":\"-\",\"PO7\":\"-\",\"PO8\":\"-\",\"PO9\":\"-\",\"PO10\":\"-\",\"PO11\":\"-\"}}}', '[\"Engineering Graphics with AUTOCAD - P I Varghese (VIP Publishers)\",\"Engineering Graphics - K. C John (PHI Learning)\",\"Engineering Drawing with CAD Applications - N. D. Bhatt & V. M. Panchal\"]', NULL, NULL, '2026-08-14 10:36:18', '2026-08-14 10:36:18');


