INSERT INTO `r26_health_physical_course_files` (`id`, `batch_subject_id`, `syllabus_pdf_path`, `program`, `course_title`, `course_code`, `semester`, `type_of_course`, `teaching_scheme`, `contact_hours`, `credits`, `cie_marks`, `ese_marks`, `parsed_cos`, `parsed_modules`, `parsed_activities`, `parsed_copo`, `parsed_eval_scheme`, `parsed_textbooks`, `created_at`, `updated_at`) VALUES ('1', '11', NULL, 'Engineering', 'Health and Physical Education', 'CE-1009', 'I', 'Health & Physical', '0:0:2:0', '30', '1.0', '60', '40', '[{\"id\":\"CO1\",\"description\":\"Demonstrate understanding of personal health, hygiene, and physical fitness principles.\",\"cognitive_level\":\"Understand\"},{\"id\":\"CO2\",\"description\":\"Perform posture evaluation, warming-up exercises, and basic physical fitness assessments.\",\"cognitive_level\":\"Apply\"},{\"id\":\"CO3\",\"description\":\"Demonstrate skills, techniques, and sportsmanship in chosen games\\/athletics.\",\"cognitive_level\":\"Apply\"},{\"id\":\"CO4\",\"description\":\"Practice yoga, stress management, first aid, and lifestyle disease prevention.\",\"cognitive_level\":\"Apply\"}]', NULL, '[{\"activity_no\":\"ACT-01\",\"title\":\"Orientation, Body Mass Index (BMI) & Posture Assessment\",\"co_id\":\"CO1\",\"hours\":3},{\"activity_no\":\"ACT-02\",\"title\":\"Warming-Up Protocols & General Physical Fitness Drills\",\"co_id\":\"CO2\",\"hours\":3},{\"activity_no\":\"ACT-03\",\"title\":\"Calisthenics, Aerobics & Cardiovascular Endurance Activities\",\"co_id\":\"CO2\",\"hours\":3},{\"activity_no\":\"ACT-04\",\"title\":\"Athletic Events - Sprint, Distance Running & Relay Technique\",\"co_id\":\"CO3\",\"hours\":3},{\"activity_no\":\"ACT-05\",\"title\":\"Major Games Skill Practice (Volleyball \\/ Football \\/ Basketball \\/ Badminton)\",\"co_id\":\"CO3\",\"hours\":6},{\"activity_no\":\"ACT-06\",\"title\":\"Yogic Asanas, Pranayama & Relaxation Techniques for Stress Relief\",\"co_id\":\"CO4\",\"hours\":4},{\"activity_no\":\"ACT-07\",\"title\":\"First Aid, CPR Fundamentals & Sports Injury Management\",\"co_id\":\"CO4\",\"hours\":4},{\"activity_no\":\"ACT-08\",\"title\":\"Fitness Test Evaluation, Logbook Submission & Physical Viva\",\"co_id\":\"CO4\",\"hours\":4}]', '{\"credit\":1,\"l_t_p_r\":\"0:0:2:0\",\"cie_marks\":60,\"ese_marks\":40,\"total_hours\":30,\"mappings\":{\"CO1\":{\"PO1\":\"2\",\"PO2\":\"-\",\"PO3\":\"-\",\"PO4\":\"-\",\"PO5\":\"3\",\"PO6\":\"3\",\"PO7\":\"2\",\"PO8\":\"3\",\"PO9\":\"3\",\"PO10\":\"2\",\"PO11\":\"2\"},\"CO2\":{\"PO1\":\"2\",\"PO2\":\"-\",\"PO3\":\"-\",\"PO4\":\"-\",\"PO5\":\"3\",\"PO6\":\"3\",\"PO7\":\"2\",\"PO8\":\"3\",\"PO9\":\"3\",\"PO10\":\"2\",\"PO11\":\"2\"},\"CO3\":{\"PO1\":\"2\",\"PO2\":\"-\",\"PO3\":\"-\",\"PO4\":\"-\",\"PO5\":\"3\",\"PO6\":\"3\",\"PO7\":\"2\",\"PO8\":\"3\",\"PO9\":\"3\",\"PO10\":\"2\",\"PO11\":\"2\"},\"CO4\":{\"PO1\":\"2\",\"PO2\":\"-\",\"PO3\":\"-\",\"PO4\":\"-\",\"PO5\":\"3\",\"PO6\":\"3\",\"PO7\":\"2\",\"PO8\":\"3\",\"PO9\":\"3\",\"PO10\":\"2\",\"PO11\":\"2\"}}}', '{\"day_work\":[{\"key\":\"c1\",\"title\":\"Physical Fitness & Warm-Up\",\"max_marks\":10},{\"key\":\"c2\",\"title\":\"Skill Execution & Technique\",\"max_marks\":15},{\"key\":\"c3\",\"title\":\"Activity Logbook \\/ Record\",\"max_marks\":10},{\"key\":\"c4\",\"title\":\"Viva-Voce & Game Rules\",\"max_marks\":10},{\"key\":\"c5\",\"title\":\"Sportsmanship & Attendance\",\"max_marks\":5}],\"total_max\":50}', NULL, '2026-08-13 21:56:47', '2026-08-13 21:56:47');


