3\":\"2\",\"PO4\":\"2\",\"PO5\":\"2\",\"PO6\":\"-\",\"PO7\":\"-\",\"PO8\":\"-\",\"PO9\":\"-\",\"PO10\":\"-\",\"PO11\":\"-\"},\"CO4\":{\"PO1\":\"3\",\"PO2\":\"2\",\"PO3\":\"3\",\"PO4\":\"2\",\"PO5\":\"2\",\"PO6\":\"2\",\"PO7\":\"3\",\"PO8\":\"-\",\"PO9\":\"-\",\"PO10\":\"-\",\"PO11\":\"-\"}}}', '[\"Textbook Reference 1\",\"Textbook Reference 2\"]', '{\"CO1\":{\"assignment\":true,\"mcq\":true,\"case_study\":true,\"quiz\":true,\"activity\":true,\"microproject\":true}}', '2026-08-11 17:49:42', '2026-08-12 20:50:06', '{\"5\":{\"is_checked\":false,\"remarks\":\"Generated from course metadata\",\"updated_at\":\"2026-08-11 18:18:10\"},\"6\":{\"is_checked\":false,\"remarks\":\"CO-PO matrix mapped\",\"updated_at\":\"2026-08-11 18:18:11\"},\"7\":{\"is_checked\":false,\"remarks\":\"Institutional calendar mapped\",\"updated_at\":\"2026-08-11 18:18:11\"},\"8\":{\"is_checked\":false,\"remarks\":\"Lesson plan generated\",\"updated_at\":\"2026-08-11 18:18:12\"},\"19\":{\"is_checked\":false,\"remarks\":\"CO attainment mapped\",\"updated_at\":\"2026-08-11 18:18:34\"},\"20\":{\"is_checked\":false,\"remarks\":\"PO\\/PSO attainment calculated\",\"updated_at\":\"2026-08-11 18:18:34\"},\"16\":{\"is_checked\":false,\"remarks\":\"Table 2.2 & 3.1 Rubrics mapped\",\"updated_at\":\"2026-08-11 18:18:35\"},\"13\":{\"is_checked\":false,\"remarks\":\"Dynamic pedagogy tracking active\",\"updated_at\":\"2026-08-11 18:18:36\"},\"14\":{\"is_checked\":false,\"remarks\":\"Self-learning scheme configured\",\"updated_at\":\"2026-08-11 18:18:36\"},\"1\":{\"is_checked\":false,\"remarks\":\"Active timetable mapped\",\"updated_at\":\"2026-08-12 09:22:19\"},\"2\":{\"is_checked\":false,\"remarks\":\"Faculty allocation assigned\",\"updated_at\":\"2026-08-12 09:22:12\"}}');
INSERT INTO `r26_practicum_course_files` (`id`, `batch_subject_id`, `syllabus_pdf_path`, `program`, `course_title`, `course_code`, `semester`, `type_of_course`, `teaching_scheme`, `contact_hours`, `credits`, `cie_marks`, `ese_marks`, `parsed_cos`, `parsed_modules`, `parsed_experiments`, `parsed_copo`, `parsed_textbooks`, `self_learning_configs`, `created_at`, `updated_at`, `doc_checklist`) VALUES ('2', '37', NULL, 'Engineering', 'Basic Mechanical Engineering', 'ME-1021', '1', 'Practicum', '3:0:3:0', '90', '4.5', '40', '100', '[{\"id\":\"CO1\",\"description\":\"Demonstrate basic concepts, electrical quantities, signal types, and electronic measuring instruments.\",\"cognitive_level\":\"Apply\"},{\"id\":\"CO2\",\"description\":\"Construct and analyze basic electronic circuits using passive electronic components.\",\"cognitive_level\":\"Apply\"},{\"id\":\"CO3\",\"description\":\"Apply semiconductor theory to demonstrate the operation of semiconductor devices.\",\"cognitive_level\":\"Apply\"},{\"id\":\"CO4\",\"description\":\"Demonstrate Printed Circuit Boards and apply soldering techniques.\",\"cognitive_level\":\"Apply\"}]', '[{\"module_id\":\"I\",\"title\":\"Introduction to Electronics, Signals and Measurements\",\"content\":\"Introduction, applications, electrical quantities, signals, lab familiarization\",\"hours\":11},{\"module_id\":\"II\",\"title\":\"Passive Electronic Components\",\"content\":\"Resistors, capacitors, inductors, transformers, series\\/parallel testing\",\"hours\":12},{\"module_id\":\"III\",\"title\":\"Active Electronic Components\",\"content\":\"Semiconductor theory, PN junction diode, Zener diode, LED, photodiode\",\"hours\":12},{\"module_id\":\"IV\",\"title\":\"PCB and Soldering\",\"content\":\"PCB types, layout design, fabrication steps, soldering practice\",\"hours\":10}]', '[{\"experiment_no\":\"EXP-01\",\"title\":\"Familiarization of electronics labs and measuring instruments\",\"co_id\":\"CO1\",\"hours\":3},{\"experiment_no\":\"EXP-02\",\"title\":\"Identification and testing of passive components\",\"co_id\":\"CO2\",\"hours\":3},{\"experiment_no\":\"EXP-03\",\"title\":\"Series and Parallel Resistor circuit construction and testing\",\"co_id\":\"CO2\",\"hours\":3},{\"experiment_no\":\"EXP-04\",\"title\":\"Series and Parallel Capacitor circuit construction and testing\",\"co_id\":\"CO2\",\"hours\":3},{\"experiment_no\":\"EXP-05\",\"title\":\"Identification of PN Junction Diode and plotting VI characteristics\",\"co_id\":\"CO3\",\"hours\":3},{\"experiment_no\":\"EXP-06\",\"title\":\"Plotting VI characteristics of Zener Diode\",\"co_id\":\"CO3\",\"hours\":3},{\"experiment_no\":\"EXP-07\",\"title\":\"PCB layout preparation and soldering practice\",\"co_id\":\"CO4\",\"hours\":3},{\"experiment_no\":\"EXP-08\",\"title\":\"Identification and testing of BJT Transistors\",\"co_id\":\"CO3\",\"hours\":3},{\"experiment_no\":\"EXP-09\",\"title\":\"Half wave rectifier circuit assembly and waveform measurement\",\"co_id\":\"CO3\",\"hours\":3},{\"experiment_no\":\"EXP-10\",\"title\":\"Full wave center-tapped rectifier circuit assembly and testing\",\"co_id\":\"CO3\",\"hours\":3},{\"experiment_no\":\"EXP-11\",\"title\":\"Capacitor filter circuit testing with DC output ripple analysis\",\"co_id\":\"CO3\",\"hours\":3},{\"experiment_no\":\"EXP-12\",\"title\":\"Logic gate IC pinout familiarization and truth table verification\",\"co_id\":\"CO4\",\"hours\":3},{\"experiment_no\":\"EXP-13\",\"title\":\"Through-hole component soldering on general purpose PCB\",\"co_id\":\"CO4\",\"hours\":3},{\"experiment_no\":\"EXP-14\",\"title\":\"Desoldering techniques and component replacement practice\",\"co_id\":\"CO4\",\"hours\":3},{\"experiment_no\":\"EXP-15\",\"title\":\"Mini hardware project circuit testing and troubleshooting\",\"co_id\":\"CO4\",\"hours\":3}]', '{\"credit\":4.5,\"l_t_p_r\":\"3:0:3:0\",\"cie_marks\":40,\"ese_marks\":100,\"total_hours\":90,\"mappings\":{\"CO1\":{\"PO1\":\"3\",\"PO2\":\"2\",\"PO3\":\"1\",\"PO4\":\"3\",\"PO5\":\"2\",\"PO6\":\"1\",\"PO7\":\"-\",\"PO8\":\"-\",\"PO9\":\"-\",\"PO10\":\"-\",\"PO11\":\"1\"},\"CO2\":{\"PO1\":\"3\",\"PO2\":\"2\",\"PO3\":\"2\",\"PO4\":\"3\",\"PO5\":\"2\",\"PO6\":\"1\",\"PO7\":\"-\",\"PO8\":\"-\",\"PO9\":\"-\",\"PO10\":\"-\",\"PO11\":\"1\"},\"CO3\":{\"PO1\":\"3\",\"PO2\":\"2\",\"PO3\":\"2\",\"PO4\":\"3\",\"PO5\":\"2\",\"PO6\":\"-\",\"PO7\":\"-\",\"PO8\":\"-\",\"PO9\":\"-\",\"PO10\":\"-\",\"PO11\":\"1\"},\"CO4\":{\"PO1\":\"3\",\"PO2\":\"2\",\"PO3\":\"1\",\"PO4\":\"2\",\"PO5\":\"2\",\"PO6\":\"-\",\"PO7\":\"-\",\"PO8\":\"-\",\"PO9\":\"-\",\"PO10\":\"-\",\"PO11\":\"1\"}}}', '[\"Electronic Inventions and Discoveries - G.W.A Drummer\",\"Grob\'s Basic Electronics - Mitchel E. Schultz\",\"Textbook of Electrical Technology: Part 1 - B.L. Thereja\"]', '{\"CO1\":{\"assignment\":5,\"mcq\":5},\"CO2\":{\"assignment\":5,\"mcq\":5},\"CO3\":{\"assignment\":5,\"mcq\":5},\"CO4\":{\"assignment\":5,\"mcq\":5}}', '2026-08-14 23:37:44', '2026-08-14 23:37:44', NULL);


CREATE TABLE `r26_practicum_ese_marks` (
